diffs.replacement:
import React, { useState, useEffect, useRef } from 'react';
import { Expense, Currency, ExpenseCategory, Personnel, AttachedFile } from '../types';
import { IconPlus, IconTrash, IconEdit, IconCheck, IconSearch, IconFileText, IconWallet, IconClock, IconUsers, IconRefreshCw, IconMoney, IconAlertTriangle } from './Icons';
import { saveExpense, updateExpense, deleteExpense, subscribeToExpenses, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

export const ExpenseManager: React.FC<Props> = ({ currentUser, personnel, lang }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Filter States
  const [categoryFilter, setCategoryFilter] = useState<ExpenseCategory | 'all'>('all');
  const [personnelFilter, setPersonnelFilter] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [dateFilter, setDateFilter] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Expense>>({
    title: '',
    amount: 0,
    paidAmount: 0,
    currency: 'IRR',
    category: 'operational',
    date: new Date().toISOString().split('T')[0],
    paidTo: '',
    personnelId: '',
    description: '',
    status: 'paid',
    files: []
  });

  const [displayAmount, setDisplayAmount] = useState('');
  const [displayPaidAmount, setDisplayPaidAmount] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');

  useEffect(() => {
    const unsub = subscribeToExpenses(setExpenses);
    return () => unsub();
  }, []);

  const t = {
    fa: {
      header: 'مدیریت هزینه‌ها و واریزی‌ها',
      sub: 'ثبت و پایش هزینه‌های عملیاتی، غیرعملیاتی و پرداختی به اشخاص',
      add: 'ثبت هزینه جدید',
      edit: 'ویرایش هزینه',
      payPortion: 'ثبت پرداخت مرحله‌ای',
      title: 'عنوان هزینه',
      amount: 'مبلغ کل هزینه',
      paidAmount: 'مبلغ پرداخت شده تا کنون',
      currency: 'ارز',
      category: 'دسته‌بندی',
      date: 'تاریخ ثبت/پرداخت',
      paidTo: 'پرداخت شده به (نام شخص/شرکت)',
      linkedStaff: 'مرتبط با پرسنل',
      desc: 'توضیحات / جزئیات',
      status: 'وضعیت تسویه',
      receipt: 'پیوست رسید / فاکتور',
      save: 'ذخیره نهایی',
      cancel: 'انصراف',
      categories: {
        all: 'همه دسته‌ها',
        operational: 'هزینه عملیاتی',
        non_operational: 'هزینه غیرعملیاتی',
        salary: 'حقوق و مزایا',
        sales_commission: 'کمیسیون فروش',
        designer_commission: 'کمیسیون طراح',
        marketing: 'تبلیغات و مارکتینگ',
        rent: 'اجاره و قبوض',
        tax: 'مالیات و عوارض',
        other: 'سایر موارد'
      },
      table: {
        title: 'شرح',
        amount: 'مبلغ (پرداخت / کل)',
        cat: 'نوع',
        to: 'گیرنده',
        date: 'تاریخ',
        status: 'وضعیت',
        balance: 'مانده بدهی'
      },
      stats: {
        total: 'کل فاکتورها',
        paid: 'مجموع پرداختی‌ها',
        remaining: 'مانده معوقات (بدهی)',
        count: 'تعداد تراکنش'
      },
      filters: {
        allPersonnel: 'همه پرسنل',
        staffSelect: 'فیلتر پرسنل'
      },
      paid: 'تسویه شده',
      pending: 'در انتظار پرداخت',
      partial: 'پرداخت بخشی',
      deleteConfirm: 'آیا از حذف این رکورد هزینه اطمینان دارید؟',
      uploading: 'در حال آپلود...',
      empty: 'هزینه‌ای یافت نشد.',
      noLink: 'بدون ارتباط پرسنلی (متفرقه)',
      remained: 'مانده نهایی:',
      newPayment: 'مبلغ پرداختی جدید'
    },
    en: {
      header: 'Expenses & Payments',
      sub: 'Track operational, non-operational costs and person payments',
      add: 'New Expense',
      edit: 'Edit Expense',
      payPortion: 'Record Partial Payment',
      title: 'Title',
      amount: 'Total Amount',
      paidAmount: 'Amount Paid So Far',
      currency: 'Currency',
      category: 'Category',
      date: 'Date',
      paidTo: 'Paid To (Name)',
      linkedStaff: 'Linked Personnel',
      desc: 'Description',
      status: 'Settlement Status',
      receipt: 'Receipt / Attachment',
      save: 'Save Expense',
      cancel: 'Cancel',
      categories: {
        all: 'All Categories',
        operational: 'Operational',
        non_operational: 'Non-Operational',
        salary: 'Salary & Benefits',
        sales_commission: 'Sales Commission',
        designer_commission: 'Designer Commission',
        marketing: 'Marketing',
        rent: 'Rent & Utilities',
        tax: 'Tax & Fees',
        other: 'Others'
      },
      table: {
        title: 'Description',
        amount: 'Amount (Paid / Total)',
        cat: 'Type',
        to: 'Receiver',
        date: 'Date',
        status: 'Status',
        balance: 'Balance'
      },
      stats: {
        total: 'Total Invoices',
        paid: 'Total Disbursed',
        remaining: 'Total Arrears',
        count: 'Trans. Count'
      },
      filters: {
        allPersonnel: 'All Staff',
        staffSelect: 'Filter Staff'
      },
      paid: 'Paid',
      pending: 'Pending',
      partial: 'Partially Paid',
      deleteConfirm: 'Are you sure you want to delete this expense record?',
      uploading: 'Uploading...',
      empty: 'No expenses found.',
      noLink: 'No Link',
      remained: 'Remaining:',
      newPayment: 'New Payment Amount'
    }
  }[lang];

  const filteredExpenses = expenses.filter(ex => {
    const matchesCat = categoryFilter === 'all' || ex.category === categoryFilter;
    const matchesSearch = ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || ex.paidTo.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDate = !dateFilter || ex.date.startsWith(dateFilter);
    const matchesPersonnel = personnelFilter === 'all' || ex.personnelId === personnelFilter;
    return matchesCat && matchesSearch && matchesDate && matchesPersonnel;
  });

  // Calculate stats per currency
  const getStatsByCurrency = () => {
    const totals: Record<string, { total: number, paid: number, remaining: number }> = {};

    filteredExpenses.forEach(ex => {
      const cur = ex.currency || 'IRR';
      if (!totals[cur]) totals[cur] = { total: 0, paid: 0, remaining: 0 };

      const amt = ex.amount || 0;
      const pd = ex.paidAmount || 0;

      totals[cur].total += amt;
      totals[cur].paid += pd;
      totals[cur].remaining += (amt - pd);
    });

    return totals;
  };

  const currencyStats = getStatsByCurrency();
  const activeCurrencies = Object.keys(currencyStats);

  const normalizeDigits = (val: string) => {
    return val.toString()
      .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d).toString())
      .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d).toString());
  };

  const formatDisplayAmount = (val: string) => {
    const normalized = normalizeDigits(val);
    const clean = normalized.replace(/\D/g, "");
    return clean.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  };

  const handleAmountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    const formatted = formatDisplayAmount(rawValue);
    setDisplayAmount(formatted);
    const numericValue = parseFloat(formatted.replace(/,/g, '')) || 0;
    setFormData(prev => ({ ...prev, amount: numericValue }));
  };

  const handlePaidAmountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    const formatted = formatDisplayAmount(rawValue);
    setDisplayPaidAmount(formatted);
    const numericValue = parseFloat(formatted.replace(/,/g, '')) || 0;
    setFormData(prev => ({ ...prev, paidAmount: numericValue }));
  };

  const handleOpenAdd = () => {
    setEditingExpense(null);
    setFormData({ title: '', amount: 0, paidAmount: 0, currency: 'IRR', category: 'operational', date: new Date().toISOString().split('T')[0], paidTo: '', personnelId: '', description: '', status: 'paid', files: [] });
    setDisplayAmount('');
    setDisplayPaidAmount('');
    setShowAddModal(true);
  };

  const handleOpenEdit = (ex: Expense) => {
    setEditingExpense(ex);
    setFormData({ ...ex, personnelId: ex.personnelId || '' });
    setDisplayAmount(ex.amount.toLocaleString());
    setDisplayPaidAmount((ex.paidAmount || 0).toLocaleString());
    setShowAddModal(true);
  };

  const handleOpenPayment = (ex: Expense) => {
    setShowPaymentModal(ex);
    setFormData({ ...ex });
    setDisplayPaidAmount(''); // New amount to add
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.amount) return;
    setIsSubmitting(true);

    const amount = Number(formData.amount);
    const paid = Number(formData.paidAmount || 0);

    let status: 'paid' | 'pending' | 'partial' = 'pending';
    if (paid >= amount) status = 'paid';
    else if (paid > 0) status = 'partial';

    const expense: Expense = {
      id: editingExpense?.id || `exp-${Date.now()}`,
      title: formData.title!,
      amount: amount,
      paidAmount: paid,
      currency: formData.currency as Currency,
      category: formData.category as ExpenseCategory,
      date: formData.date!,
      paidTo: formData.paidTo!,
      personnelId: formData.personnelId || undefined,
      description: formData.description,
      files: formData.files,
      status: status,
      createdAt: editingExpense?.createdAt || new Date().toISOString(),
      createdBy: editingExpense?.createdBy || currentUser.fullName
    };

    if (editingExpense) {
      await updateExpense(expense.id, expense, currentUser.fullName);
    } else {
      await saveExpense(expense, currentUser.fullName);
    }

    setIsSubmitting(false);
    setShowAddModal(false);
    setEditingExpense(null);
  };

  const handleSavePayment = async () => {
    if (!showPaymentModal) return;
    setIsSubmitting(true);

    const newAddition = parseFloat(normalizeDigits(displayPaidAmount).replace(/,/g, '')) || 0;
    const currentPaid = showPaymentModal.paidAmount || 0;
    const totalPaid = currentPaid + newAddition;
    const totalAmount = showPaymentModal.amount;

    let status: 'paid' | 'pending' | 'partial' = 'pending';
    if (totalPaid >= totalAmount) status = 'paid';
    else if (totalPaid > 0) status = 'partial';

    await updateExpense(showPaymentModal.id, {
        paidAmount: totalPaid,
        status: status
    }, currentUser.fullName);

    setIsSubmitting(false);
    setShowPaymentModal(null);
  };

  const handleDelete = async (id: string) => {
    if (window.confirm(t.deleteConfirm)) {
      await deleteExpense(id, currentUser.fullName);
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
    setFormData(prev => ({ ...prev, files: [...(prev.files || []), newFile] }));

    uploadFileWithProgress(
      file,
      (progress) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, progress } : f) }));
      },
      (url) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f) }));
      },
      (err) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, status: 'error' } : f) }));
      }
    );
  };

  const getPersonnelName = (id?: string) => {
    if (!id) return null;
    return personnel.find(p => p.id === id)?.fullName;
  };

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'paid': return 'bg-green-100 text-green-700';
      case 'partial': return 'bg-amber-100 text-amber-700 ring-2 ring-amber-500/20'; // Highlight partial in amber
      default: return 'bg-red-50 text-red-700 ring-1 ring-red-200';
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'paid': return t.paid;
      case 'partial': return t.partial;
      default: return t.pending;
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <div className="bg-rose-100 text-rose-600 p-2 rounded-lg"><IconWallet className="w-6 h-6" /></div>
            {t.header}
          </h2>
          <p className="text-sm text-gray-500 mt-1">{t.sub}</p>
        </div>
        <button onClick={handleOpenAdd} className="bg-rose-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-rose-700 flex items-center gap-2 shadow-lg shadow-rose-200 transition-all">
          <IconPlus className="w-5 h-5" /> {t.add}
        </button>
      </div>

      {/* Stats Cards - Multi-currency Support */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {/* Total Expenses Card - Highlighting "What should be paid" in yellow/amber */}
        <div className="bg-amber-50 p-5 rounded-2xl border-2 border-amber-200 shadow-sm">
          <div className="text-amber-800 text-xs font-black mb-2 uppercase tracking-tight flex items-center gap-1">
             <IconAlertTriangle className="w-3 h-3" /> {t.stats.total}
          </div>
          <div className="space-y-1">
            {activeCurrencies.length > 0 ? activeCurrencies.map(cur => (
              <div key={cur} className="text-lg font-black text-amber-900 flex justify-between items-baseline">
                <span>{currencyStats[cur].total.toLocaleString()}</span>
                <span className="text-[10px] text-amber-600 font-bold mr-1">{cur}</span>
              </div>
            )) : <div className="text-xl font-black text-amber-200">0</div>}
          </div>
        </div>

        {/* Paid Expenses Card */}
        <div className="bg-green-50 p-5 rounded-2xl border border-green-100 shadow-sm">
          <div className="text-green-700 text-xs font-bold mb-2">{t.stats.paid}</div>
          <div className="space-y-1">
            {activeCurrencies.length > 0 ? activeCurrencies.map(cur => (
              <div key={cur} className="text-lg font-black text-green-600 flex justify-between items-baseline">
                <span>{currencyStats[cur].paid.toLocaleString()}</span>
                <span className="text-[10px] text-green-400 font-bold mr-1">{cur}</span>
              </div>
            )) : <div className="text-xl font-black text-green-200">0</div>}
          </div>
        </div>

        {/* Remaining (Arrears) Card - Highlighting in high-contrast yellow/amber */}
        <div className="bg-yellow-100 p-5 rounded-2xl border-2 border-yellow-400 shadow-lg ring-4 ring-yellow-400/10">
          <div className="text-yellow-900 text-xs font-black mb-2 flex items-center gap-1">
             <IconClock className="w-3 h-3" /> {t.stats.remaining}
          </div>
          <div className="space-y-1">
            {activeCurrencies.length > 0 ? activeCurrencies.map(cur => (
              <div key={cur} className="text-xl font-black text-yellow-900 flex justify-between items-baseline drop-shadow-sm">
                <span>{currencyStats[cur].remaining.toLocaleString()}</span>
                <span className="text-[10px] text-yellow-700 font-black mr-1">{cur}</span>
              </div>
            )) : <div className="text-xl font-black text-yellow-300">0</div>}
          </div>
        </div>

        {/* Transaction Count Card */}
        <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100 shadow-sm">
          <div className="text-gray-500 text-xs font-bold mb-1">{t.stats.count}</div>
          <div className="text-3xl font-black text-gray-600 mt-2">{filteredExpenses.length}</div>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col lg:flex-row gap-4 items-center">
        <div className="relative flex-grow w-full">
          <IconSearch className="absolute right-3 top-3 w-4 h-4 text-gray-400" />
          <input 
            className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-rose-100" 
            placeholder="جستجو در شرح هزینه یا گیرنده..." 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
          />
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 w-full lg:w-auto">
          <select 
            className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-gray-600 outline-none" 
            value={categoryFilter} 
            onChange={e => setCategoryFilter(e.target.value as any)}
          >
            <option value="all">{t.categories.all}</option>
            {Object.keys(t.categories).filter(k => k !== 'all').map(cat => <option key={cat} value={cat}>{t.categories[cat as keyof typeof t.categories]}</option>)}
          </select>

          <select 
            className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-indigo-600 outline-none"
            value={personnelFilter}
            onChange={e => setPersonnelFilter(e.target.value)}
          >
            <option value="all">{t.filters.allPersonnel}</option>
            {personnel.map(p => (
              <option key={p.id} value={p.id}>{p.fullName}</option>
            ))}
          </select>

          <input 
            type="month" 
            className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-gray-600 outline-none" 
            value={dateFilter} 
            onChange={e => setDateFilter(e.target.value)} 
          />
        </div>
        <button onClick={() => {setSearchTerm(''); setCategoryFilter('all'); setPersonnelFilter('all'); setDateFilter('');}} className="p-2.5 text-gray-400 hover:text-rose-600 transition-colors" title="ریست فیلترها">
          <IconRefreshCw className="w-5 h-5" />
        </button>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right text-sm">
            <thead className="bg-gray-50 text-gray-500 font-bold uppercase tracking-wider">
              <tr>
                <th className="px-6 py-4">{t.table.title}</th>
                <th className="px-6 py-4">{t.table.amount}</th>
                <th className="px-6 py-4 text-amber-700 bg-amber-50/50">{t.table.balance}</th>
                <th className="px-6 py-4">{t.table.cat}</th>
                <th className="px-6 py-4">{t.table.to}</th>
                <th className="px-6 py-4 text-center">{t.table.status}</th>
                <th className="px-6 py-4 text-center">عملیات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredExpenses.map(ex => {
                const remaining = ex.amount - (ex.paidAmount || 0);
                return (
                  <tr key={ex.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="font-bold text-gray-800">{ex.title}</div>
                      {ex.personnelId && (
                        <div className="text-[10px] text-indigo-500 flex items-center gap-1 mt-1 font-bold">
                          <IconUsers className="w-3 h-3" /> {getPersonnelName(ex.personnelId)}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex flex-col">
                          <span className="font-black text-gray-700">{(ex.paidAmount || 0).toLocaleString()} <span className="text-[10px] font-normal opacity-50">/ {ex.amount.toLocaleString()}</span></span>
                          <div className="flex items-center gap-1 mt-1">
                              <div className="w-20 bg-gray-100 h-1 rounded-full overflow-hidden">
                                  <div className={`h-full ${ex.status === 'partial' ? 'bg-amber-500' : (ex.status === 'paid' ? 'bg-green-500' : 'bg-red-500')}`} style={{ width: `${Math.min(100, ((ex.paidAmount || 0) / ex.amount) * 100)}%` }}></div>
                              </div>
                              <span className="text-[9px] font-bold text-gray-400 uppercase">{ex.currency}</span>
                          </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                        {remaining > 0 ? (
                            <div className="flex flex-col">
                                <span className="text-amber-600 font-black text-base">{remaining.toLocaleString()}</span>
                                <span className="text-[9px] font-bold text-amber-400 uppercase">{ex.currency}</span>
                            </div>
                        ) : (
                            <span className="text-green-500 font-bold text-xs"><IconCheck className="w-3 h-3 inline mr-1" /> تسویه</span>
                        )}
                    </td>
                    <td className="px-6 py-4"><span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{t.categories[ex.category as keyof typeof t.categories]}</span></td>
                    <td className="px-6 py-4 text-gray-600 font-medium">{ex.paidTo}</td>
                    <td className="px-6 py-4 text-center">
                      <span className={`px-2 py-1 rounded text-[10px] font-bold ${getStatusBadge(ex.status)}`}>
                        {getStatusLabel(ex.status)}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex justify-center gap-1">
                        <button onClick={() => handleOpenPayment(ex)} className="p-1.5 text-green-500 hover:text-green-700 hover:bg-green-50 rounded-lg" title={t.payPortion}><IconMoney className="w-4 h-4" /></button>
                        <button onClick={() => handleOpenEdit(ex)} className="p-1.5 text-blue-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><IconEdit className="w-4 h-4" /></button>
                        {isMaster && <button onClick={() => handleDelete(ex.id)} className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><IconTrash className="w-4 h-4" /></button>}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredExpenses.length === 0 && (
                <tr>
                  <td colSpan={7} className="text-center py-20 text-gray-400">
                    <IconWallet className="w-12 h-12 mx-auto mb-3 opacity-20" />
                    <p className="font-bold">{t.empty}</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Main Add/Edit Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-gray-900/60 backdrop-blur-md p-4 animate-fade-in" onClick={() => setShowAddModal(false)}>
          <div className="bg-white rounded-[2rem] w-full max-w-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]" onClick={e => e.stopPropagation()}>
            <div className="p-6 border-b border-gray-100 bg-rose-50 flex justify-between items-center">
              <h3 className="font-black text-xl text-rose-900 flex items-center gap-2"><IconWallet className="w-5 h-5" />{editingExpense ? t.edit : t.add}</h3>
              <button onClick={() => setShowAddModal(false)} className="p-2 hover:bg-rose-100 rounded-full">✕</button>
            </div>
            <form onSubmit={handleSave} className="p-8 overflow-y-auto space-y-6 custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.title}</label>
                  <input required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 transition-all font-bold" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} placeholder="مثلاً: هزینه خرید تجهیزات..." />
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.amount}</label>
                  <div className="flex gap-2">
                    <div className="relative flex-grow">
                      <input 
                        type="text" 
                        required 
                        className="w-full px-4 py-3 rounded-xl border-2 border-amber-100 outline-none focus:border-amber-500 transition-all font-black text-amber-700 dir-ltr text-right" 
                        value={displayAmount} 
                        onChange={handleAmountInputChange} 
                        placeholder="0" 
                      />
                    </div>
                    <select className="w-24 px-2 border rounded-xl bg-gray-50 outline-none font-bold" value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as any})}>
                      <option value="IRR">ریال</option>
                      <option value="USD">USD</option>
                      <option value="OMR">OMR</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.paidAmount}</label>
                  <input 
                    type="text" 
                    className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 transition-all font-black text-green-600 dir-ltr text-right" 
                    value={displayPaidAmount} 
                    onChange={handlePaidAmountInputChange} 
                    placeholder="0" 
                  />
                </div>

                {formData.amount !== undefined && formData.paidAmount !== undefined && (formData.amount - formData.paidAmount > 0) && (
                    <div className="md:col-span-2 bg-yellow-50 p-4 rounded-xl border border-yellow-200 flex justify-between items-center animate-slide-in">
                        <span className="text-sm font-bold text-yellow-800">{t.remained}</span>
                        <span className="text-lg font-black text-amber-700">{(formData.amount - formData.paidAmount).toLocaleString()} {formData.currency}</span>
                    </div>
                )}

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.category}</label>
                  <select className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 bg-white font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})}>
                    {Object.keys(t.categories).filter(k => k !== 'all').map(cat => <option key={cat} value={cat}>{t.categories[cat as keyof typeof t.categories]}</option>)}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.date}</label>
                  <input type="date" required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 font-mono" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.linkedStaff}</label>
                  <select className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 bg-white font-bold text-indigo-600" value={formData.personnelId} onChange={e => setFormData({...formData, personnelId: e.target.value, paidTo: e.target.value ? (personnel.find(p=>p.id === e.target.value)?.fullName || formData.paidTo) : formData.paidTo })}>
                    <option value="">{t.noLink}</option>
                    {personnel.map(p => (
                      <option key={p.id} value={p.id}>{p.fullName} ({p.roles.join(', ')})</option>
                    ))}
                  </select>
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.paidTo}</label>
                  <input required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 font-bold" value={formData.paidTo} onChange={e => setFormData({...formData, paidTo: e.target.value})} placeholder="شخص یا شرکت" />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.desc}</label>
                  <textarea rows={2} className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 font-medium" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                </div>

                <div className="md:col-span-2">
                   <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-widest">{t.receipt}</label>
                   <div onClick={() => fileInputRef.current?.click()} className="border-2 border-dashed border-gray-200 rounded-xl p-6 text-center cursor-pointer hover:border-rose-400 hover:bg-rose-50/30 transition-all bg-gray-50">
                      <IconFileText className="w-8 h-8 text-gray-300 mx-auto mb-2" />
                      <p className="text-xs text-gray-500 font-bold">برای آپلود کلیک کنید (فاکتور، فیش واریز و ...)</p>
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />
                   </div>
                   <div className="flex flex-wrap gap-2 mt-3">
                     {formData.files?.map((f, i) => (
                       <div key={i} className="flex items-center gap-2 bg-white border border-gray-200 p-2 rounded-lg text-xs shadow-sm">
                         <IconFileText className="w-3 h-3 text-rose-500" />
                         <span className="max-w-[150px] truncate font-bold">{f.name}</span>
                         {f.status === 'uploading' && <span className="text-[10px] text-blue-500">{Math.round(f.progress || 0)}%</span>}
                         <button type="button" onClick={() => setFormData(p => ({...p, files: p.files?.filter((_, idx) => idx !== i)}))} className="text-red-400 hover:text-red-600 transition-colors">✕</button>
                       </div>
                     ))}
                   </div>
                </div>
              </div>
            </form>
            <div className="p-6 border-t border-gray-100 flex gap-3 bg-gray-50/50">
              <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 text-gray-500 font-bold hover:bg-white rounded-2xl transition-all border border-transparent hover:border-gray-200 uppercase tracking-widest">{t.cancel}</button>
              <button onClick={handleSave} disabled={isSubmitting} className="flex-1 py-3 bg-rose-600 text-white font-black rounded-2xl shadow-xl shadow-rose-200 hover:bg-rose-700 transition-all flex justify-center items-center gap-2">
                {isSubmitting ? <IconRefreshCw className="w-5 h-5 animate-spin" /> : <><IconCheck className="w-5 h-5" /> {t.save}</>}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Partial Payment Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-gray-900/60 backdrop-blur-md p-4 animate-fade-in" onClick={() => setShowPaymentModal(null)}>
            <div className="bg-white rounded-[2rem] w-full max-w-md shadow-2xl overflow-hidden flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="p-6 border-b border-gray-100 bg-green-50 flex justify-between items-center">
                    <h3 className="font-black text-lg text-green-900 flex items-center gap-2"><IconMoney className="w-5 h-5" />{t.payPortion}</h3>
                    <button onClick={() => setShowPaymentModal(null)} className="p-2 hover:bg-green-100 rounded-full">✕</button>
                </div>
                <div className="p-8 space-y-6">
                    <div>
                        <div className="text-sm font-bold text-gray-500 mb-1">{showPaymentModal.title}</div>
                        <div className="text-xs text-gray-400 mb-4">{showPaymentModal.paidTo}</div>

                        <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-200 space-y-2">
                            <div className="flex justify-between text-xs font-bold">
                                <span className="text-gray-500">{t.amount}:</span>
                                <span className="text-gray-900">{showPaymentModal.amount.toLocaleString()}</span>
                            </div>
                            <div className="flex justify-between text-xs font-bold">
                                <span className="text-gray-500">{t.paidAmount}:</span>
                                <span className="text-green-600">{(showPaymentModal.paidAmount || 0).toLocaleString()}</span>
                            </div>
                            <div className="flex justify-between text-sm font-black border-t border-yellow-300 pt-2">
                                <span className="text-yellow-800">{t.remained}</span>
                                <span className="text-amber-700">{ (showPaymentModal.amount - (showPaymentModal.paidAmount || 0)).toLocaleString() } {showPaymentModal.currency}</span>
                            </div>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-widest">{t.newPayment}</label>
                        <input 
                            type="text" 
                            autoFocus
                            className="w-full px-4 py-4 rounded-xl border-2 border-green-100 outline-none focus:border-green-500 transition-all font-black text-2xl text-green-600 dir-ltr text-center" 
                            value={displayPaidAmount} 
                            onChange={(e) => setDisplayPaidAmount(formatDisplayAmount(e.target.value))}
                            placeholder="0" 
                        />
                    </div>
                </div>
                <div className="p-6 bg-gray-50 flex gap-3">
                    <button onClick={() => setShowPaymentModal(null)} className="flex-1 py-3 text-gray-500 font-bold hover:bg-white rounded-xl transition-all">انصراف</button>
                    <button onClick={handleSavePayment} disabled={isSubmitting || !displayPaidAmount} className="flex-1 py-3 bg-green-600 text-white font-black rounded-xl shadow-lg shadow-green-200 hover:bg-green-700 transition-all flex justify-center items-center gap-2">
                        {isSubmitting ? <IconRefreshCw className="w-5 h-5 animate-spin" /> : <><IconCheck className="w-5 h-5" /> {t.save}</>}
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Expense, Currency, ExpenseCategory, Personnel, AttachedFile } from '../types';
import { IconPlus, IconTrash, IconEdit, IconCheck, IconSearch, IconFileText, IconWallet, IconClock, IconUsers, IconRefreshCw, IconMoney, IconAlertTriangle } from './Icons';
import { saveExpense, updateExpense, deleteExpense, subscribeToExpenses, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

export const ExpenseManager: React.FC<Props> = ({ currentUser, personnel, lang }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Filter States
  const [categoryFilter, setCategoryFilter] = useState<ExpenseCategory | 'all'>('all');
  const [personnelFilter, setPersonnelFilter] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [dateFilter, setDateFilter] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Expense>>({
    title: '',
    amount: 0,
    paidAmount: 0,
    currency: 'IRR',
    category: 'operational',
    date: new Date().toISOString().split('T')[0],
    paidTo: '',
    personnelId: '',
    description: '',
    status: 'paid',
    files: []
  });

  const [displayAmount, setDisplayAmount] = useState('');
  const [displayPaidAmount, setDisplayPaidAmount] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');

  useEffect(() => {
    const unsub = subscribeToExpenses(setExpenses);
    return () => unsub();
  }, []);

  const t = {
    fa: {
      header: 'مدیریت هزینه‌ها و واریزی‌ها',
      sub: 'ثبت و پایش هزینه‌های عملیاتی، غیرعملیاتی و پرداختی به اشخاص',
      add: 'ثبت هزینه جدید',
      edit: 'ویرایش هزینه',
      payPortion: 'ثبت پرداخت مرحله‌ای',
      title: 'عنوان هزینه',
      amount: 'مبلغ کل هزینه',
      paidAmount: 'مبلغ پرداخت شده تا کنون',
      currency: 'ارز',
      category: 'دسته‌بندی',
      date: 'تاریخ ثبت/پرداخت',
      paidTo: 'پرداخت شده به (نام شخص/شرکت)',
      linkedStaff: 'مرتبط با پرسنل',
      desc: 'توضیحات / جزئیات',
      status: 'وضعیت تسویه',
      receipt: 'پیوست رسید / فاکتور',
      save: 'ذخیره نهایی',
      cancel: 'انصراف',
      categories: {
        all: 'همه دسته‌ها',
        operational: 'هزینه عملیاتی',
        non_operational: 'هزینه غیرعملیاتی',
        salary: 'حقوق و مزایا',
        sales_commission: 'کمیسیون فروش',
        designer_commission: 'کمیسیون طراح',
        marketing: 'تبلیغات و مارکتینگ',
        rent: 'اجاره و قبوض',
        tax: 'مالیات و عوارض',
        other: 'سایر موارد'
      },
      table: {
        title: 'شرح',
        amount: 'مبلغ (پرداخت / کل)',
        cat: 'نوع',
        to: 'گیرنده',
        date: 'تاریخ',
        status: 'وضعیت',
        balance: 'مانده جهت پرداخت'
      },
      stats: {
        total: 'کل فاکتورها',
        paid: 'مجموع پرداختی‌ها',
        remaining: 'مانده کل معوقات (بدهی)',
        count: 'تعداد تراکنش'
      },
      filters: {
        allPersonnel: 'همه پرسنل',
        staffSelect: 'فیلتر پرسنل'
      },
      paid: 'تسویه شده',
      pending: 'در انتظار پرداخت',
      partial: 'پرداخت بخشی',
      deleteConfirm: 'آیا از حذف این رکورد هزینه اطمینان دارید؟',
      uploading: 'در حال آپلود...',
      empty: 'هزینه‌ای یافت نشد.',
      noLink: 'بدون ارتباط پرسنلی (متفرقه)',
      remained: 'مبلغ نهایی باقیمانده جهت تسویه:',
      newPayment: 'مبلغ پرداختی جدید'
    },
    en: {
      header: 'Expenses & Payments',
      sub: 'Track operational, non-operational costs and person payments',
      add: 'New Expense',
      edit: 'Edit Expense',
      payPortion: 'Record Partial Payment',
      title: 'Title',
      amount: 'Total Amount',
      paidAmount: 'Amount Paid So Far',
      currency: 'Currency',
      category: 'Category',
      date: 'Date',
      paidTo: 'Paid To (Name)',
      linkedStaff: 'Linked Personnel',
      desc: 'Description',
      status: 'Settlement Status',
      receipt: 'Receipt / Attachment',
      save: 'Save Expense',
      cancel: 'Cancel',
      categories: {
        all: 'All Categories',
        operational: 'Operational',
        non_operational: 'Non-Operational',
        salary: 'Salary & Benefits',
        sales_commission: 'Sales Commission',
        designer_commission: 'Designer Commission',
        marketing: 'Marketing',
        rent: 'Rent & Utilities',
        tax: 'Tax & Fees',
        other: 'Others'
      },
      table: {
        title: 'Description',
        amount: 'Amount (Paid / Total)',
        cat: 'Type',
        to: 'Receiver',
        date: 'Date',
        status: 'Status',
        balance: 'Final Balance'
      },
      stats: {
        total: 'Total Invoices',
        paid: 'Total Disbursed',
        remaining: 'Total Arrears',
        count: 'Trans. Count'
      },
      filters: {
        allPersonnel: 'All Staff',
        staffSelect: 'Filter Staff'
      },
      paid: 'Paid',
      pending: 'Pending',
      partial: 'Partially Paid',
      deleteConfirm: 'Are you sure you want to delete this expense record?',
      uploading: 'Uploading...',
      empty: 'No expenses found.',
      noLink: 'No Link',
      remained: 'Final Remaining Balance:',
      newPayment: 'New Payment Amount'
    }
  }[lang];

  const filteredExpenses = expenses.filter(ex => {
    const matchesCat = categoryFilter === 'all' || ex.category === categoryFilter;
    const matchesSearch = ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || ex.paidTo.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDate = !dateFilter || ex.date.startsWith(dateFilter);
    const matchesPersonnel = personnelFilter === 'all' || ex.personnelId === personnelFilter;
    return matchesCat && matchesSearch && matchesDate && matchesPersonnel;
  });

  // Calculate stats per currency
  const getStatsByCurrency = () => {
    const totals: Record<string, { total: number, paid: number, remaining: number }> = {};

    filteredExpenses.forEach(ex => {
      const cur = ex.currency || 'IRR';
      if (!totals[cur]) totals[cur] = { total: 0, paid: 0, remaining: 0 };

      const amt = ex.amount || 0;
      const pd = ex.paidAmount || 0;

      totals[cur].total += amt;
      totals[cur].paid += pd;
      totals[cur].remaining += (amt - pd);
    });

    return totals;
  };

  const currencyStats = getStatsByCurrency();
  const activeCurrencies = Object.keys(currencyStats);

  const normalizeDigits = (val: string) => {
    return val.toString()
      .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d).toString())
      .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d).toString());
  };

  const formatDisplayAmount = (val: string) => {
    const normalized = normalizeDigits(val);
    const clean = normalized.replace(/\D/g, "");
    return clean.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  };

  const handleAmountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    const formatted = formatDisplayAmount(rawValue);
    setDisplayAmount(formatted);
    const numericValue = parseFloat(formatted.replace(/,/g, '')) || 0;
    setFormData(prev => ({ ...prev, amount: numericValue }));
  };

  const handlePaidAmountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    const formatted = formatDisplayAmount(rawValue);
    setDisplayPaidAmount(formatted);
    const numericValue = parseFloat(formatted.replace(/,/g, '')) || 0;
    setFormData(prev => ({ ...prev, paidAmount: numericValue }));
  };

  const handleOpenAdd = () => {
    setEditingExpense(null);
    setFormData({ title: '', amount: 0, paidAmount: 0, currency: 'IRR', category: 'operational', date: new Date().toISOString().split('T')[0], paidTo: '', personnelId: '', description: '', status: 'paid', files: [] });
    setDisplayAmount('');
    setDisplayPaidAmount('');
    setShowAddModal(true);
  };

  const handleOpenEdit = (ex: Expense) => {
    setEditingExpense(ex);
    setFormData({ ...ex, personnelId: ex.personnelId || '' });
    setDisplayAmount(ex.amount.toLocaleString());
    setDisplayPaidAmount((ex.paidAmount || 0).toLocaleString());
    setShowAddModal(true);
  };

  const handleOpenPayment = (ex: Expense) => {
    setShowPaymentModal(ex);
    setFormData({ ...ex });
    setDisplayPaidAmount(''); // Reset input for addition
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.amount) return;
    setIsSubmitting(true);

    const amount = Number(formData.amount);
    const paid = Number(formData.paidAmount || 0);

    let status: 'paid' | 'pending' | 'partial' = 'pending';
    if (paid >= amount) status = 'paid';
    else if (paid > 0) status = 'partial';

    const expense: Expense = {
      id: editingExpense?.id || `exp-${Date.now()}`,
      title: formData.title!,
      amount: amount,
      paidAmount: paid,
      currency: formData.currency as Currency,
      category: formData.category as ExpenseCategory,
      date: formData.date!,
      paidTo: formData.paidTo!,
      personnelId: formData.personnelId || undefined,
      description: formData.description,
      files: formData.files,
      status: status,
      createdAt: editingExpense?.createdAt || new Date().toISOString(),
      createdBy: editingExpense?.createdBy || currentUser.fullName
    };

    if (editingExpense) {
      await updateExpense(expense.id, expense, currentUser.fullName);
    } else {
      await saveExpense(expense, currentUser.fullName);
    }

    setIsSubmitting(false);
    setShowAddModal(false);
    setEditingExpense(null);
  };

  const handleSavePayment = async () => {
    if (!showPaymentModal) return;
    setIsSubmitting(true);

    const newAddition = parseFloat(normalizeDigits(displayPaidAmount).replace(/,/g, '')) || 0;
    const currentPaid = showPaymentModal.paidAmount || 0;
    const totalPaid = currentPaid + newAddition;
    const totalAmount = showPaymentModal.amount;

    let status: 'paid' | 'pending' | 'partial' = 'pending';
    if (totalPaid >= totalAmount) status = 'paid';
    else if (totalPaid > 0) status = 'partial';

    await updateExpense(showPaymentModal.id, {
        paidAmount: totalPaid,
        status: status
    }, currentUser.fullName);

    setIsSubmitting(false);
    setShowPaymentModal(null);
  };

  const handleDelete = async (id: string) => {
    if (window.confirm(t.deleteConfirm)) {
      await deleteExpense(id, currentUser.fullName);
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
    setFormData(prev => ({ ...prev, files: [...(prev.files || []), newFile] }));

    uploadFileWithProgress(
      file,
      (progress) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, progress } : f) }));
      },
      (url) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f) }));
      },
      (err) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, status: 'error' } : f) }));
      }
    );
  };

  const getPersonnelName = (id?: string) => {
    if (!id) return null;
    return personnel.find(p => p.id === id)?.fullName;
  };

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'paid': return 'bg-green-100 text-green-700';
      case 'partial': return 'bg-amber-100 text-amber-700 ring-2 ring-amber-500/20';
      default: return 'bg-red-50 text-red-700 ring-1 ring-red-200';
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'paid': return t.paid;
      case 'partial': return t.partial;
      default: return t.pending;
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <div className="bg-rose-100 text-rose-600 p-2 rounded-lg"><IconWallet className="w-6 h-6" /></div>
            {t.header}
          </h2>
          <p className="text-sm text-gray-500 mt-1">{t.sub}</p>
        </div>
        <button onClick={handleOpenAdd} className="bg-rose-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-rose-700 flex items-center gap-2 shadow-lg shadow-rose-200 transition-all">
          <IconPlus className="w-5 h-5" /> {t.add}
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {/* Total card */}
        <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
          <div className="text-gray-500 text-xs font-bold mb-2">{t.stats.total}</div>
          <div className="space-y-1">
            {activeCurrencies.length > 0 ? activeCurrencies.map(cur => (
              <div key={cur} className="text-lg font-black text-gray-800 flex justify-between items-baseline">
                <span>{currencyStats[cur].total.toLocaleString()}</span>
                <span className="text-[10px] text-gray-400 font-bold mr-1">{cur}</span>
              </div>
            )) : <div className="text-xl font-black text-gray-200">0</div>}
          </div>
        </div>

        {/* Paid card */}
        <div className="bg-green-50 p-5 rounded-2xl border border-green-100 shadow-sm">
          <div className="text-green-700 text-xs font-bold mb-2">{t.stats.paid}</div>
          <div className="space-y-1">
            {activeCurrencies.length > 0 ? activeCurrencies.map(cur => (
              <div key={cur} className="text-lg font-black text-green-600 flex justify-between items-baseline">
                <span>{currencyStats[cur].paid.toLocaleString()}</span>
                <span className="text-[10px] text-green-400 font-bold mr-1">{cur}</span>
              </div>
            )) : <div className="text-xl font-black text-green-200">0</div>}
          </div>
        </div>

        {/* Highlighted Remaining card - requested Yellow/Amber */}
        <div className="bg-yellow-100 p-5 rounded-2xl border-2 border-yellow-400 shadow-lg ring-4 ring-yellow-400/10 scale-[1.02]">
          <div className="text-yellow-900 text-xs font-black mb-2 flex items-center gap-1">
             <IconClock className="w-3 h-3" /> {t.stats.remaining}
          </div>
          <div className="space-y-1">
            {activeCurrencies.length > 0 ? activeCurrencies.map(cur => (
              <div key={cur} className="text-xl font-black text-yellow-900 flex justify-between items-baseline drop-shadow-sm">
                <span>{currencyStats[cur].remaining.toLocaleString()}</span>
                <span className="text-[10px] text-yellow-700 font-black mr-1">{cur}</span>
              </div>
            )) : <div className="text-xl font-black text-yellow-300">0</div>}
          </div>
        </div>

        <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100 shadow-sm">
          <div className="text-gray-500 text-xs font-bold mb-1">{t.stats.count}</div>
          <div className="text-3xl font-black text-gray-600 mt-2">{filteredExpenses.length}</div>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col lg:flex-row gap-4 items-center">
        <div className="relative flex-grow w-full">
          <IconSearch className="absolute right-3 top-3 w-4 h-4 text-gray-400" />
          <input 
            className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-rose-100" 
            placeholder="جستجو در شرح یا گیرنده..." 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
          />
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 w-full lg:w-auto">
          <select className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-gray-600 outline-none" value={categoryFilter} onChange={e => setCategoryFilter(e.target.value as any)}>
            <option value="all">{t.categories.all}</option>
            {Object.keys(t.categories).filter(k => k !== 'all').map(cat => <option key={cat} value={cat}>{t.categories[cat as keyof typeof t.categories]}</option>)}
          </select>
          <select className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-indigo-600 outline-none" value={personnelFilter} onChange={e => setPersonnelFilter(e.target.value)}>
            <option value="all">{t.filters.allPersonnel}</option>
            {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
          </select>
          <input type="month" className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-gray-600 outline-none" value={dateFilter} onChange={e => setDateFilter(e.target.value)} />
        </div>
        <button onClick={() => {setSearchTerm(''); setCategoryFilter('all'); setPersonnelFilter('all'); setDateFilter('');}} className="p-2.5 text-gray-400 hover:text-rose-600 transition-colors">
          <IconRefreshCw className="w-5 h-5" />
        </button>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right text-sm">
            <thead className="bg-gray-50 text-gray-500 font-bold uppercase tracking-wider">
              <tr>
                <th className="px-6 py-4">{t.table.title}</th>
                <th className="px-6 py-4">{t.table.amount}</th>
                <th className="px-6 py-4 text-amber-700 bg-amber-50/50">{t.table.balance}</th>
                <th className="px-6 py-4">{t.table.cat}</th>
                <th className="px-6 py-4">{t.table.to}</th>
                <th className="px-6 py-4 text-center">{t.table.status}</th>
                <th className="px-6 py-4 text-center">عملیات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredExpenses.map(ex => {
                const remaining = ex.amount - (ex.paidAmount || 0);
                return (
                  <tr key={ex.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="font-bold text-gray-800">{ex.title}</div>
                      {ex.personnelId && (
                        <div className="text-[10px] text-indigo-500 flex items-center gap-1 mt-1 font-bold">
                          <IconUsers className="w-3 h-3" /> {getPersonnelName(ex.personnelId)}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex flex-col">
                          <span className="font-black text-gray-700">{(ex.paidAmount || 0).toLocaleString()} <span className="text-[10px] font-normal opacity-50">/ {ex.amount.toLocaleString()}</span></span>
                          <div className="flex items-center gap-1 mt-1">
                              <div className="w-20 bg-gray-100 h-1 rounded-full overflow-hidden">
                                  <div className={`h-full ${ex.status === 'partial' ? 'bg-amber-500' : (ex.status === 'paid' ? 'bg-green-500' : 'bg-red-500')}`} style={{ width: `${Math.min(100, ((ex.paidAmount || 0) / ex.amount) * 100)}%` }}></div>
                              </div>
                              <span className="text-[9px] font-bold text-gray-400 uppercase">{ex.currency}</span>
                          </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                        {remaining > 0 ? (
                            <div className="flex flex-col">
                                <span className="text-amber-600 font-black text-base">{remaining.toLocaleString()}</span>
                                <span className="text-[9px] font-bold text-amber-400 uppercase">{ex.currency}</span>
                            </div>
                        ) : (
                            <span className="text-green-500 font-bold text-xs"><IconCheck className="w-3 h-3 inline mr-1" /> تسویه شده</span>
                        )}
                    </td>
                    <td className="px-6 py-4"><span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{t.categories[ex.category as keyof typeof t.categories]}</span></td>
                    <td className="px-6 py-4 text-gray-600 font-medium">{ex.paidTo}</td>
                    <td className="px-6 py-4 text-center">
                      <span className={`px-2 py-1 rounded text-[10px] font-bold ${getStatusBadge(ex.status)}`}>
                        {getStatusLabel(ex.status)}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex justify-center gap-1">
                        <button onClick={() => handleOpenPayment(ex)} className="p-1.5 text-green-500 hover:text-green-700 hover:bg-green-50 rounded-lg" title={t.payPortion}><IconMoney className="w-4 h-4" /></button>
                        <button onClick={() => handleOpenEdit(ex)} className="p-1.5 text-blue-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><IconEdit className="w-4 h-4" /></button>
                        {isMaster && <button onClick={() => handleDelete(ex.id)} className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><IconTrash className="w-4 h-4" /></button>}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredExpenses.length === 0 && (
                <tr>
                  <td colSpan={7} className="text-center py-20 text-gray-400">
                    <IconWallet className="w-12 h-12 mx-auto mb-3 opacity-20" />
                    <p className="font-bold">{t.empty}</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add/Edit Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-gray-900/60 backdrop-blur-md p-4 animate-fade-in" onClick={() => setShowAddModal(false)}>
          <div className="bg-white rounded-[2rem] w-full max-w-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]" onClick={e => e.stopPropagation()}>
            <div className="p-6 border-b border-gray-100 bg-rose-50 flex justify-between items-center">
              <h3 className="font-black text-xl text-rose-900 flex items-center gap-2"><IconWallet className="w-5 h-5" />{editingExpense ? t.edit : t.add}</h3>
              <button onClick={() => setShowAddModal(false)} className="p-2 hover:bg-rose-100 rounded-full">✕</button>
            </div>
            <form onSubmit={handleSave} className="p-8 overflow-y-auto space-y-6 custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.title}</label>
                  <input required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 transition-all font-bold" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} placeholder="مثلاً: هزینه خرید تجهیزات..." />
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.amount}</label>
                  <div className="flex gap-2">
                    <div className="relative flex-grow">
                      <input type="text" required className="w-full px-4 py-3 rounded-xl border-2 border-amber-100 outline-none focus:border-amber-500 transition-all font-black text-amber-700 dir-ltr text-right" value={displayAmount} onChange={handleAmountInputChange} placeholder="0" />
                    </div>
                    <select className="w-24 px-2 border rounded-xl bg-gray-50 outline-none font-bold" value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as any})}>
                      <option value="IRR">ریال</option>
                      <option value="USD">USD</option>
                      <option value="OMR">OMR</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.paidAmount}</label>
                  <input type="text" className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 transition-all font-black text-green-600 dir-ltr text-right" value={displayPaidAmount} onChange={handlePaidAmountInputChange} placeholder="0" />
                </div>

                {/* VISUAL CALCULATION BOX */}
                {formData.amount !== undefined && formData.paidAmount !== undefined && (formData.amount - formData.paidAmount > 0) && (
                    <div className="md:col-span-2 bg-yellow-50 p-4 rounded-xl border border-yellow-200 flex justify-between items-center animate-slide-in">
                        <span className="text-sm font-bold text-yellow-800">{t.remained}</span>
                        <span className="text-lg font-black text-amber-700">{(formData.amount - formData.paidAmount).toLocaleString()} {formData.currency}</span>
                    </div>
                )}

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.category}</label>
                  <select className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 bg-white font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})}>
                    {Object.keys(t.categories).filter(k => k !== 'all').map(cat => <option key={cat} value={cat}>{t.categories[cat as keyof typeof t.categories]}</option>)}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.date}</label>
                  <input type="date" required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 font-mono" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.linkedStaff}</label>
                  <select className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 bg-white font-bold text-indigo-600" value={formData.personnelId} onChange={e => setFormData({...formData, personnelId: e.target.value, paidTo: e.target.value ? (personnel.find(p=>p.id === e.target.value)?.fullName || formData.paidTo) : formData.paidTo })}>
                    <option value="">{t.noLink}</option>
                    {personnel.map(p => (
                      <option key={p.id} value={p.id}>{p.fullName} ({p.roles.join(', ')})</option>
                    ))}
                  </select>
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.paidTo}</label>
                  <input required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 font-bold" value={formData.paidTo} onChange={e => setFormData({...formData, paidTo: e.target.value})} placeholder="شخص یا شرکت" />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.desc}</label>
                  <textarea rows={2} className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 font-medium" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                </div>

                <div className="md:col-span-2">
                   <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-widest">{t.receipt}</label>
                   <div onClick={() => fileInputRef.current?.click()} className="border-2 border-dashed border-gray-200 rounded-xl p-6 text-center cursor-pointer hover:border-rose-400 hover:bg-rose-50/30 transition-all bg-gray-50">
                      <IconFileText className="w-8 h-8 text-gray-300 mx-auto mb-2" />
                      <p className="text-xs text-gray-500 font-bold">برای آپلود کلیک کنید (فاکتور، فیش واریز و ...)</p>
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />
                   </div>
                   <div className="flex flex-wrap gap-2 mt-3">
                     {formData.files?.map((f, i) => (
                       <div key={i} className="flex items-center gap-2 bg-white border border-gray-200 p-2 rounded-lg text-xs shadow-sm">
                         <IconFileText className="w-3 h-3 text-rose-500" />
                         <span className="max-w-[150px] truncate font-bold">{f.name}</span>
                         {f.status === 'uploading' && <span className="text-[10px] text-blue-500">{Math.round(f.progress || 0)}%</span>}
                         <button type="button" onClick={() => setFormData(p => ({...p, files: p.files?.filter((_, idx) => idx !== i)}))} className="text-red-400 hover:text-red-600 transition-colors">✕</button>
                       </div>
                     ))}
                   </div>
                </div>
              </div>
            </form>
            <div className="p-6 border-t border-gray-100 flex gap-3 bg-gray-50/50">
              <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 text-gray-500 font-bold hover:bg-white rounded-2xl transition-all border border-transparent hover:border-gray-200 uppercase tracking-widest">{t.cancel}</button>
              <button onClick={handleSave} disabled={isSubmitting} className="flex-1 py-3 bg-rose-600 text-white font-black rounded-2xl shadow-xl shadow-rose-200 hover:bg-rose-700 transition-all flex justify-center items-center gap-2">
                {isSubmitting ? <IconRefreshCw className="w-5 h-5 animate-spin" /> : <><IconCheck className="w-5 h-5" /> {t.save}</>}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Partial Payment Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-gray-900/60 backdrop-blur-md p-4 animate-fade-in" onClick={() => setShowPaymentModal(null)}>
            <div className="bg-white rounded-[2rem] w-full max-w-md shadow-2xl overflow-hidden flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="p-6 border-b border-gray-100 bg-green-50 flex justify-between items-center">
                    <h3 className="font-black text-lg text-green-900 flex items-center gap-2"><IconMoney className="w-5 h-5" />{t.payPortion}</h3>
                    <button onClick={() => setShowPaymentModal(null)} className="p-2 hover:bg-green-100 rounded-full">✕</button>
                </div>
                <div className="p-8 space-y-6">
                    <div>
                        <div className="text-sm font-bold text-gray-500 mb-1">{showPaymentModal.title}</div>
                        <div className="text-xs text-gray-400 mb-4">{showPaymentModal.paidTo}</div>

                        <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-200 space-y-2">
                            <div className="flex justify-between text-xs font-bold">
                                <span className="text-gray-500">{t.amount}:</span>
                                <span className="text-gray-900">{showPaymentModal.amount.toLocaleString()}</span>
                            </div>
                            <div className="flex justify-between text-xs font-bold">
                                <span className="text-gray-500">{t.paidAmount}:</span>
                                <span className="text-green-600">{(showPaymentModal.paidAmount || 0).toLocaleString()}</span>
                            </div>
                            <div className="flex justify-between text-sm font-black border-t border-yellow-300 pt-2">
                                <span className="text-yellow-800">مانده باقیمانده (بدهی):</span>
                                <span className="text-amber-700">{ (showPaymentModal.amount - (showPaymentModal.paidAmount || 0)).toLocaleString() } {showPaymentModal.currency}</span>
                            </div>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-widest">{t.newPayment}</label>
                        <input 
                            type="text" 
                            autoFocus
                            className="w-full px-4 py-4 rounded-xl border-2 border-green-100 outline-none focus:border-green-500 transition-all font-black text-2xl text-green-600 dir-ltr text-center" 
                            value={displayPaidAmount} 
                            onChange={(e) => setDisplayPaidAmount(formatDisplayAmount(e.target.value))}
                            placeholder="0" 
                        />
                    </div>
                </div>
                <div className="p-6 bg-gray-50 flex gap-3">
                    <button onClick={() => setShowPaymentModal(null)} className="flex-1 py-3 text-gray-500 font-bold hover:bg-white rounded-xl transition-all">انصراف</button>
                    <button onClick={handleSavePayment} disabled={isSubmitting || !displayPaidAmount} className="flex-1 py-3 bg-green-600 text-white font-black rounded-xl shadow-lg shadow-green-200 hover:bg-green-700 transition-all flex justify-center items-center gap-2">
                        {isSubmitting ? <IconRefreshCw className="w-5 h-5 animate-spin" /> : <><IconCheck className="w-5 h-5" /> {t.save}</>}
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};
